using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Management;
using Microsoft.Win32;
using System.Windows;
using System.Text;
namespace WindowsOptimizerForAll {
 public static class SystemActions {
  public static string DetectWindows(){try{using(var k=Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion")){string p=Convert.ToString(k.GetValue("ProductName","Windows"));string v=Convert.ToString(k.GetValue("CurrentVersion",""));if(p.IndexOf("Windows 11",StringComparison.OrdinalIgnoreCase)>=0)return "Windows 11";if(v.StartsWith("6.1"))return "Windows 7";if(v.StartsWith("6.2")||v.StartsWith("6.3"))return "Windows 8 / 8.1";if(v.StartsWith("10."))return "Windows 10 / 11";return p;}}catch{return Environment.OSVersion.VersionString;}}
  public static string DetectGpu(){try{using(var s=new ManagementObjectSearcher("select Name from Win32_VideoController")){foreach(ManagementObject m in s.Get()){string n=Convert.ToString(m["Name"]);if(!String.IsNullOrEmpty(n))return n;}}}catch{}return "Не определена";}
  public static string GetHardwareSummary(){var b=new StringBuilder();AppendWmi(b,"Win32_Processor","Name",Localization.T("Процессор"));AppendWmi(b,"Win32_VideoController","Name",Localization.T("Видеокарта"));AppendWmi(b,"Win32_BaseBoard","Manufacturer,Product",Localization.T("Материнская плата"));try{using(var s=new ManagementObjectSearcher("select TotalPhysicalMemory from Win32_ComputerSystem")){foreach(ManagementObject m in s.Get()){ulong bytes=Convert.ToUInt64(m["TotalPhysicalMemory"]);b.AppendLine(Localization.T("Оперативная память")+": "+(bytes/1073741824.0).ToString("0.0")+" GB");}}}catch{}AppendWmi(b,"Win32_DiskDrive","Model,Size",Localization.T("Накопитель"));return b.Length==0?Localization.T("Не удалось получить сведения об оборудовании."):b.ToString().TrimEnd();}
  static void AppendWmi(StringBuilder b,string className,string properties,string label){try{using(var s=new ManagementObjectSearcher("select "+properties+" from "+className)){foreach(ManagementObject m in s.Get()){var values=new List<string>();foreach(string p in properties.Split(',')){object value=m[p.Trim()];if(value==null)continue;string text=Convert.ToString(value);if(p.Trim().Equals("Size",StringComparison.OrdinalIgnoreCase)){ulong bytes; if(UInt64.TryParse(text,out bytes))text=(bytes/1073741824.0).ToString("0.0")+" GB";}if(!String.IsNullOrWhiteSpace(text))values.Add(text);}if(values.Count>0)b.AppendLine(label+": "+String.Join(" — ",values.ToArray()));}}}catch{}}
  static string NativeSystemDirectory(){if(Environment.Is64BitOperatingSystem&&!Environment.Is64BitProcess)return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"Sysnative");return Environment.SystemDirectory;}
  public static void OpenSystemProtection(){string exe=Path.Combine(NativeSystemDirectory(),"SystemPropertiesProtection.exe");if(!File.Exists(exe))throw new FileNotFoundException(Localization.T("Окно защиты системы не найдено."),exe);Process.Start(new ProcessStartInfo(exe){UseShellExecute=true});}
  public static void EnableSystemProtection(){string drive=Path.GetPathRoot(Environment.SystemDirectory);using(ManagementClass c=new ManagementClass(@"\\.\root\default:SystemRestore")){ManagementBaseObject input=c.GetMethodParameters("Enable");input["Drive"]=drive;using(ManagementBaseObject output=c.InvokeMethod("Enable",input,null)){if(output==null||Convert.ToUInt32(output["ReturnValue"])!=0)throw new Exception(Localization.T("Windows не смогла включить защиту системы."));}}}
  public static void MoveRestoreStorage(string destinationRoot,int maxSizeGb){string source=Path.GetPathRoot(Environment.SystemDirectory);if(String.IsNullOrWhiteSpace(destinationRoot)||!System.Text.RegularExpressions.Regex.IsMatch(destinationRoot,"^[A-Za-z]:\\\\$")||String.Equals(source,destinationRoot,StringComparison.OrdinalIgnoreCase))throw new ArgumentException(Localization.T("Выберите другой локальный диск для хранилища."));if(maxSizeGb<1||maxSizeGb>2048)throw new ArgumentOutOfRangeException("maxSizeGb",Localization.T("Укажите размер от 1 до 2048 ГБ."));DriveInfo drive=new DriveInfo(destinationRoot);if(!drive.IsReady||drive.DriveType!=DriveType.Fixed)throw new InvalidOperationException(Localization.T("Выбранный диск недоступен."));string exe=Path.Combine(NativeSystemDirectory(),"vssadmin.exe");var start=new ProcessStartInfo(exe,"resize shadowstorage /for="+source.TrimEnd('\\')+" /on="+destinationRoot.TrimEnd('\\')+" /maxsize="+maxSizeGb+"GB"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(Process p=Process.Start(start)){string output=p.StandardOutput.ReadToEnd();string error=p.StandardError.ReadToEnd();p.WaitForExit();if(p.ExitCode!=0)throw new InvalidOperationException(Localization.T("Windows не смогла изменить диск хранилища точек.")+" "+output+" "+error);}}
  public static void Run(string exe,string args){string name=Path.GetFileName(exe);if(!String.Equals(name,exe,StringComparison.OrdinalIgnoreCase)||!(name.Equals("powercfg.exe",StringComparison.OrdinalIgnoreCase)||name.Equals("sc.exe",StringComparison.OrdinalIgnoreCase)||name.Equals("wmic.exe",StringComparison.OrdinalIgnoreCase)||name.Equals("ipconfig.exe",StringComparison.OrdinalIgnoreCase)))throw new InvalidOperationException(Localization.T("Запуск этой системной команды не разрешён."));string fullPath=Path.Combine(Environment.SystemDirectory,name);if(!File.Exists(fullPath))throw new FileNotFoundException(Localization.T("Системная команда не найдена."),fullPath);var p=new ProcessStartInfo(fullPath,args);p.UseShellExecute=false;p.CreateNoWindow=true;using(Process x=Process.Start(p)){x.WaitForExit();if(x.ExitCode!=0)throw new Exception(name+Localization.T(" завершился с кодом ")+x.ExitCode);}}
  public static void SetDword(string path,string name,int value){using(var k=Registry.CurrentUser.CreateSubKey(path)){k.SetValue(name,value,RegistryValueKind.DWord);}}
  public static void SetDwordMachine(string path,string name,int value){using(var k=Registry.LocalMachine.CreateSubKey(path)){k.SetValue(name,value,RegistryValueKind.DWord);}}
  public static void CleanTemp(){string local=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);string windows=Environment.GetFolderPath(Environment.SpecialFolder.Windows);string[] paths={String.IsNullOrWhiteSpace(local)?null:Path.Combine(local,"Temp"),String.IsNullOrWhiteSpace(windows)?null:Path.Combine(windows,"Temp")};foreach(string path in paths){if(String.IsNullOrWhiteSpace(path)||!Directory.Exists(path))continue;DirectoryInfo root=new DirectoryInfo(path);if((root.Attributes&FileAttributes.ReparsePoint)!=0)continue;DeleteTempContents(root);}}
  static void DeleteTempContents(DirectoryInfo directory){FileInfo[] files;DirectoryInfo[] folders;try{files=directory.GetFiles();folders=directory.GetDirectories();}catch{return;}foreach(FileInfo file in files){try{file.Delete();}catch{}}foreach(DirectoryInfo folder in folders){try{if((folder.Attributes&FileAttributes.ReparsePoint)!=0)folder.Delete(false);else{DeleteTempContents(folder);folder.Delete(false);}}catch{}}}
  public static void CreateRestorePoint(){try{using(ManagementClass c=new ManagementClass(@"\\.\root\default:SystemRestore")){ManagementBaseObject input=c.GetMethodParameters("CreateRestorePoint");input["Description"]="Windows Optimizer for All — "+Localization.T("точка перед изменениями");input["RestorePointType"]=(uint)12;input["EventType"]=(uint)100;using(ManagementBaseObject output=c.InvokeMethod("CreateRestorePoint",input,null)){if(output==null||Convert.ToUInt32(output["ReturnValue"])!=0)throw new Exception(Localization.T("WMI не смог создать точку восстановления."));}}}catch(Exception e){throw new Exception(Localization.T("Не удалось создать точку восстановления. Проверьте, включена ли защита системы. ")+e.Message);}}
  public static void StopService(string name){if(!String.Equals(name,"SysMain",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException(Localization.T("Изменение этой службы не разрешено."));Run("sc.exe","config \"SysMain\" start= demand");}
  public static string GetActivePowerScheme(){string exe=Path.Combine(NativeSystemDirectory(),"powercfg.exe");var p=new ProcessStartInfo(exe,"/getactivescheme"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(Process process=Process.Start(p)){string output=process.StandardOutput.ReadToEnd();string error=process.StandardError.ReadToEnd();process.WaitForExit();if(process.ExitCode!=0)throw new InvalidOperationException(output+error);var match=System.Text.RegularExpressions.Regex.Match(output,@"[0-9a-fA-F]{8}-(?:[0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}");if(!match.Success)throw new InvalidOperationException("Could not read the active power scheme.");return match.Value;}}
  public static void SetActivePowerScheme(string guid){Guid parsed;if(!Guid.TryParse(guid,out parsed))throw new ArgumentException("Invalid power scheme identifier.");Run("powercfg.exe","/setactive "+parsed.ToString());}
  public static void RestoreServiceStartup(int value){string start=value==2?"auto":value==3?"demand":value==4?"disabled":null;if(start==null)throw new InvalidOperationException("Unsupported SysMain startup type; restore it in Services.");Run("sc.exe","config \"SysMain\" start= "+start);}
 }
}
